import urllib.request, json, datetime

# Get token
cfg = json.load(open("/Users/edy/.openclaw/openclaw.json"))["channels"]["feishu"]
req = urllib.request.Request(
    'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal',
    data=json.dumps({"app_id": cfg["appId"], "app_secret": cfg["appSecret"]}).encode(),
    headers={'Content-Type': 'application/json'}
)
token = json.loads(urllib.request.urlopen(req).read())["tenant_access_token"]

APP_TOKEN = "TAxUbXUmKaXVuXsNWOacbP1Tne1"
TABLE_ID = "tblJ7fKHxchaECKz"

# Get field IDs first
fields_req = urllib.request.Request(
    f'https://open.feishu.cn/open-apis/bitable/v1/apps/{APP_TOKEN}/tables/{TABLE_ID}/fields',
    headers={"Authorization": f"Bearer {token}"}
)
fields_resp = json.loads(urllib.request.urlopen(fields_req).read())
field_map = {f["field_name"]: f["field_id"] for f in fields_resp["data"]["items"]}
print("Field map:", json.dumps(field_map, ensure_ascii=False))

# Create record
record_data = {
    "fields": {
        "学科": "地理",
        "题目内容": "（1）①省级行政区名称是______，位于我国四大地理区域中的______地区，主要的粮食作物是______；④特别行政区名称是______。",
        "正确答案": "①湖南省，青藏地区，水稻（/小麦）；④香港特别行政区",
        "错因分析": "不能正确识别省级行政区轮廓和地理位置，不知道湖南省的形状特征，不知道香港特别行政区的位置",
        "知识点": "省份识别, 香港地理, 一国两制",
        "难度": "⭐⭐",
        "录入时间": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "备注": "图片上传失败，截图见原消息"
    }
}

create_req = urllib.request.Request(
    f'https://open.feishu.cn/open-apis/bitable/v1/apps/{APP_TOKEN}/tables/{TABLE_ID}/records',
    data=json.dumps(record_data).encode(),
    headers={
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    },
    method="POST"
)
try:
    resp = json.loads(urllib.request.urlopen(create_req).read())
    print("Create result:", json.dumps(resp, ensure_ascii=False)[:500])
except Exception as e:
    print(f"Error: {e}")
    try:
        import urllib.error
        if hasattr(e, 'read'):
            print("Body:", e.read().decode()[:500])
    except:
        pass
PYEOF

