    '-H', 'Content-Type: application/json',
    '-d', json.dumps({"app_id": "cli_a93534f5edb85bd3", "app_secret": json.load(open(os.path.expanduser("~/.openclaw/openclaw.json")))["channels"]["feishu"]["appSecret"]})
], capture_output=True, text=True)
