# Try to call MiniMax API directly with V06 model using the API key from OpenClaw
# First check if there's a way to get the API key
node << 'EOF'
const https = require('https');
const fs = require('fs');
const { execSync } = require('child_process');

// Try to find the API key in keychain or config
try {
  // Check openclaw config for any stored credentials
  const cfg = JSON.parse(fs.readFileSync(process.env.HOME + '/.openclaw/openclaw.json'), 'utf8');
  console.log('Config keys:', Object.keys(cfg));

  // Check if there's an apiKey somewhere
  const str = JSON.stringify(cfg);
  if (str.includes('apiKey')) console.log('Has apiKey field');
  if (str.includes('sk-')) console.log('Has sk- field');
} catch(e) {
  console.log('Error:', e.message);
}
EOF

